 auto args=listingArgs();currentKey=view==REMOTE?L"search:"+lower(trim(text(query))):view==UPDATES?L"updates":L"installed"; auto c=readCache(currentKey);
 if(c.exists){packages=parse(c.output);filter();setStatus(L"Cached · "+std::to_wstring(visible.size())+L" packages · "+std::to_wstring(std::max(0ll,c.age)/60)+L" minutes old");}else{packages.clear();filter();}
