 case WM_CTLCOLORSTATIC:case WM_CTLCOLOREDIT:{HDC dc=(HDC)wp;bool field=(HWND)lp==query||(HWND)lp==logBox;SetTextColor(dc,palette.foreground);SetBkColor(dc,field?palette.field:palette.background);return (LRESULT)(field?fieldBrush:backgroundBrush);}
 case WM_GETMINMAXINFO:((MINMAXINFO*)lp)->ptMinTrackSize={900,600};return 0;
