  bool ok=c->error.empty()&&c->result.code==0&&!c->result.timeout;
  if(c->listing&&listSuccess(c->result)&&(!c->result.output.empty()||c->error.empty())){packages=parse(c->result.output);filter();setStatus(L"Live · "+std::to_wstring(visible.size())+L" packages"+(!c->error.empty()?L" · cache unavailable":L" · cached for next launch"));}
